// =====================================================================
//  AI POWER MONITOR - SETTINGS
//  Edit the values below, then press Deploy. Everything else reads
//  from here (flow context "settings"). Deploying re-applies them.
// =====================================================================
const S = {

  // ---- MQTT details handed to the M5Stack by GET /stopwatch/configuration
  mqtt: {
    advertiseHost: "192.168.0.36",   // broker address as the M5Stack sees it
    advertisePort: 1883,
    user: "mat",                         // leave "" for anonymous
    password: "Paj0MQTT",
    // NOTE: the "M5Stack reset" MQTT-IN node has its topic typed in the node itself.
    // If you change resetTopic here, change it there too.
    telemetryTopic: "notenoughtech/ai/stopwatch/telemetry", // live (1 s) + history -> M5Stack
    resetTopic:     "notenoughtech/ai/stopwatch/reset",     // M5Stack publishes here (hold blue key)
    detailTopic:    "notenoughtech/ai/stopwatch/detail"     // full detail incl. cloud costs (retained)
  },

  // ---- Netio JSON API power input (polled by the "GET netio.json" node: URL + poll interval are set on that node / its inject)
  netio: {
    outputId: 1,          // which output the PC is plugged into (Outputs[].ID)
    useTotalLoad: false,  // true = use GlobalMeasure.TotalLoad instead of the single output
    scale: 1,             // multiply the reading to get Watts (normally 1)
    staleSec: 30          // ignore readings older than this (no energy is counted if Netio goes quiet)
  },

  // ---- AI task detection (REST POST /ai/task from the PC)
  task: {
    timeoutSec: 60,           // auto-stop if no task update arrives for this long. 0 = never (use if the PC only sends start/stop)
    inferFromGpu: true,       // a payload with only gpu_pct (no event) starts a task when gpu_pct >= threshold
    gpuActiveThresholdPct: 5
  },

  // ---- Session (starts when the M5Stack reset is pressed)
  session: {
    timeMode: "active"        // "active" = AI compute seconds since reset, "wall" = clock time since reset
  },

  // ---- Isolating AI power from the rest of the PC
  power: {
    idleBaselineW: 0,         // watts the PC draws anyway; subtracted while a task runs. 0 = count total PC power
    autoBaseline: false,      // true = learn the baseline from power drawn while NO AI task is running (overrides idleBaselineW)
    autoBaselineAlpha: 0.01   // learning speed (per second)
  },

  // ---- Electricity price
  tariff: {
    currency: "GBP",          // shown on the M5Stack (max 4 chars)
    ratePerKwh: 0.36,         // GBP per kWh - SET YOUR OWN
    offPeak: {                // optional cheap window (e.g. Octopus Go). Crosses midnight OK.
      enabled: false,
      start: "00:30",
      end: "05:30",
      ratePerKwh: 0.075
    }
  },

  // ---- Local GPU -> token estimate (RTX 2080 8GB)
  tokens: {
    localTokensPerSecond: 50, // generation speed of your usual model. 7-8B Q4 on a 2080 8GB: roughly 28-85 t/s depending on model/runtime
    minGpuPct: 80,            // tokens are only counted while GPU load is at/above this %. Power is counted for ANY GPU activity during a task. 0 = always count tokens
    scaleByGpuPct: true,      // scale tokens by the reported gpu_pct (50% busy = half the tokens)
    inputShare: 0.75          // blend used for cloud prices: 0.75 = 3 input tokens for every 1 output token
  },

  // ---- Currency conversion for cloud prices (they are quoted in USD)
  fx: { usdToGbp: 0.7514 },   // 19 Oct 2026

  // ---- Cloud API price list, USD per 1M tokens (list prices, no caching/batch discounts).
  //      Add, remove or edit freely. enabled:false hides one without deleting it.
  cloud: [
    { name: "OpenAI GPT-5.5",          inputUsdPerMTok: 5.00, outputUsdPerMTok: 30.00, enabled: true },
    { name: "OpenAI GPT-5.4",          inputUsdPerMTok: 2.50, outputUsdPerMTok: 15.00, enabled: true },
    { name: "OpenAI GPT-5.4 mini",     inputUsdPerMTok: 0.75, outputUsdPerMTok: 4.50,  enabled: true },
    { name: "Anthropic Claude Sonnet 5.5", inputUsdPerMTok: 2.00, outputUsdPerMTok: 10.00, enabled: true },
    { name: "Anthropic Claude Haiku 5.5",  inputUsdPerMTok: 0.10, outputUsdPerMTok: 0.50,  enabled: true },
    { name: "Google Gemini 3.1 Pro",   inputUsdPerMTok: 2.00, outputUsdPerMTok: 12.00, enabled: true },
    { name: "Google Gemini 3 Flash",   inputUsdPerMTok: 0.50, outputUsdPerMTok: 3.00,  enabled: true },
    { name: "Google Gemini 3.1 Flash-Lite", inputUsdPerMTok: 0.25, outputUsdPerMTok: 1.50, enabled: true },
    { name: "DeepSeek V4-Flash",       inputUsdPerMTok: 0.14, outputUsdPerMTok: 0.28,  enabled: true },  // cache-miss input price, Jul 2026
    { name: "DeepSeek V4-Pro",         inputUsdPerMTok: 0.435, outputUsdPerMTok: 0.87, enabled: true }
  ],

  // ---- LLM info from the PC (EventGhost reads Ollama /api/ps + nvidia-smi)
  llm: {
    staleSec: 90              // hide the model line on the M5Stack if the PC has not reported for this long
  },

  // ---- History (kept in Node-RED context, no database)
  history: {
    days: 30,                 // the M5Stack charts up to 30
    repeatSec: 3600,          // re-publish history this often (also on task stop, on session reset, and after the M5Stack fetches its config)
    publishOnTaskStop: true
  }
};


// ---------------------------------------------------------------------
// apply + make sure runtime context exists (never wipes your history)
// ---------------------------------------------------------------------
flow.set('settings', S);
if (!flow.get('session')) flow.set('session', { start: Date.now(), seconds: 0, wh: 0, cost: 0, tokens: 0 });
if (!flow.get('daily')) flow.set('daily', {});
if (!flow.get('recent')) flow.set('recent', []);
const t = flow.get('task') || {};
t.active = false;               // the next task update from the PC re-activates it
flow.set('task', t);

const bad = [];
if (!(S.tokens.inputShare >= 0 && S.tokens.inputShare <= 1)) bad.push('tokens.inputShare must be 0..1');
if (!(S.tokens.minGpuPct >= 0 && S.tokens.minGpuPct <= 100)) bad.push('tokens.minGpuPct must be 0..100');
if (!(S.tariff.ratePerKwh >= 0)) bad.push('tariff.ratePerKwh');
if (bad.length) node.warn('Settings problem: ' + bad.join(', '));
node.status({ fill: bad.length ? 'yellow' : 'green', shape: 'dot', text: 'settings applied ' + new Date().toLocaleTimeString() });
return null;

// GET /stopwatch/configuration  ->  what the M5Stack needs to connect to MQTT
const S = flow.get('settings');
if (!S) {
    msg.statusCode = 503;
    msg.payload = { error: 'settings not loaded yet' };
    return [msg, null];
}
const M = S.mqtt;
const mqtt = {
    host: M.advertiseHost,
    port: M.advertisePort,
    topic: M.telemetryTopic,          // the channel the data is streamed to
    reset_topic: M.resetTopic,        // where the M5Stack publishes its session reset
    keepalive: 60
};
if (M.user) { mqtt.user = M.user; mqtt.password = M.password || ''; }

msg.statusCode = 200;
msg.headers = { 'Cache-Control': 'no-store' };
msg.payload = {
    mqtt: mqtt,
    currency: S.tariff.currency,
    detail_topic: M.detailTopic
};
node.status({ fill: 'blue', shape: 'dot', text: 'config served ' + new Date().toLocaleTimeString() });

// the M5Stack connects to MQTT right after this call, so push the history shortly after
return [msg, { kind: 'history' }];

// Netio JSON API (http://<netio>/netio.json) -> latest power in Watts (flow context "power")
// Input: msg.payload = parsed JSON from the HTTP request node.
//   useTotalLoad false -> Outputs[ID == outputId].Load   (just the PC's socket)
//   useTotalLoad true  -> GlobalMeasure.TotalLoad        (whole device)
const S = flow.get('settings');
if (!S) return null;
const N = S.netio;

if (msg.statusCode !== undefined && msg.statusCode !== 200) {
    const why = msg.statusCode === 401 ? 'auth needed - set username/password on the GET netio.json node' : 'HTTP ' + msg.statusCode;
    node.status({ fill: 'red', shape: 'ring', text: why });
    return null;
}

let v = msg.payload;
if (Buffer.isBuffer(v)) v = v.toString();
if (typeof v === 'string') { try { v = JSON.parse(v); } catch (e) { /* leave as string */ } }

let load;
if (v !== null && typeof v === 'object') {
    const outs = Array.isArray(v.Outputs) ? v.Outputs : [];
    const id = Number(N.outputId);
    if (!N.useTotalLoad) {
        const o = outs.find((x) => Number(x.ID) === id);
        if (!o) {
            node.status({ fill: 'red', shape: 'ring', text: 'output ' + id + ' not in netio.json' });
            return null;
        }
        load = o.Load;
    } else if (v.GlobalMeasure && v.GlobalMeasure.TotalLoad !== undefined) {
        load = v.GlobalMeasure.TotalLoad;
    } else {
        load = outs.reduce((a, x) => a + (Number(x.Load) || 0), 0);
    }
} else {
    load = v;                          // plain number fallback
}

const w = Number(load) * (N.scale || 1);
if (load === undefined || load === null || load === '' || !isFinite(w)) {
    node.status({ fill: 'red', shape: 'ring', text: 'no Load in reply' });
    return null;
}

flow.set('power', { w: w, ts: Date.now() });
node.status({ fill: 'green', shape: 'dot', text: w.toFixed(0) + ' W' + (v && v.Agent && v.Agent.DeviceName ? '  (' + v.Agent.DeviceName + ')' : '') });
return null;

// HTTP request to the Netio failed (unreachable / timeout). Power simply stops updating;
// the integrator ignores it once it is older than netio.staleSec.
const text = String((msg.error && msg.error.message) || 'request failed').slice(0, 40);
node.status({ fill: 'red', shape: 'ring', text: 'netio: ' + text });
return null;

// POST /ai/task  <- the PC reports AI activity.
// Body (any of these names work), e.g.
//   {"event":"start","gpu_pct":0,"task":"ollama llama3","start":"2026-10-19T19:50:00Z"}
//   {"event":"update","gpu_pct":87}                      (heartbeat while running)
//   {"event":"stop","stop":"2026-10-19T19:58:12Z"}
//   {"state":"running"|"idle", "gpu":55}
//   {"gpu_pct":72}                                       (only starts a task if inferFromGpu is on)
// Output 1 -> HTTP response, output 2 -> history publish (on stop)
const S = flow.get('settings');
const reply = (code, body) => { msg.statusCode = code; msg.payload = body; return msg; };
if (!S) return [reply(503, { error: 'settings not loaded yet' }), null];

const now = Date.now();
let b = msg.payload;
if (Buffer.isBuffer(b)) b = b.toString();
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = null; } }
if (!b || typeof b !== 'object' || Array.isArray(b)) {
    return [reply(400, { error: 'send a JSON object, e.g. {"event":"start","gpu_pct":50}' }), null];
}

const pick = (...keys) => {
    for (const k of keys) {
        if (b[k] !== undefined && b[k] !== null && b[k] !== '') return b[k];
    }
    return undefined;
};
const toMs = (v) => {
    if (v === undefined) return null;
    if (typeof v === 'number') return v < 1e11 ? v * 1000 : v;
    const t = Date.parse(v);
    if (!isNaN(t)) return t;
    const n = Number(v);
    return isFinite(n) ? (n < 1e11 ? n * 1000 : n) : null;
};
const dk = (d) => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');

let gpu = pick('gpu_pct', 'gpu', 'gpu_percent', 'gpu_usage', 'gpu_utilization', 'utilization', 'util');
gpu = gpu === undefined ? null : Number(gpu);
if (gpu !== null && !isFinite(gpu)) gpu = null;
if (gpu !== null) gpu = Math.max(0, Math.min(100, gpu));

const evt = String(pick('event', 'state', 'status', 'action') ?? '').toLowerCase();
const START = ['start', 'started', 'begin', 'running', 'active', 'busy', 'on', 'true', '1'];
const STOP = ['stop', 'stopped', 'end', 'ended', 'finished', 'done', 'idle', 'inactive', 'off', 'complete', 'completed', 'false', '0'];
const startV = pick('start', 'started', 'start_time', 'started_at');
const stopV = pick('stop', 'stopped', 'stop_time', 'stopped_at', 'end', 'ended', 'end_time');

let action = 'update';
if (evt === 'info') action = 'info';
else if (START.includes(evt)) action = 'start';
else if (STOP.includes(evt)) action = 'stop';
else if (stopV !== undefined) action = 'stop';
else if (startV !== undefined) action = 'start';

const thr = S.task.gpuActiveThresholdPct ?? 5;
const task = flow.get('task') || { active: false };
let histTrig = null;

if (gpu !== null) { task.gpu = gpu; task.gpuTs = now; }
const name = pick('task', 'name', 'job', 'model');

function begin() {
    task.active = true;
    task.startedAt = toMs(startV) || now;
    task.lastEventTs = now;
    task.name = name !== undefined ? String(name) : '';
    task.acc = { seconds: 0, wh: 0, cost: 0, tokens: 0 };
    const daily = flow.get('daily') || {};
    const day = dk(new Date(now));
    const bucket = daily[day] || (daily[day] = { wh: 0, seconds: 0, cost: 0, tokens: 0, tasks: 0 });
    bucket.tasks = (bucket.tasks || 0) + 1;
    flow.set('daily', daily);
}
function finish(reason) {
    const a = task.acc || { seconds: 0, wh: 0, cost: 0, tokens: 0 };
    const rec = flow.get('recent') || [];
    rec.unshift({
        name: task.name || '',
        start: new Date(task.startedAt || now).toISOString(),
        stop: new Date(toMs(stopV) || now).toISOString(),
        seconds: Math.round(a.seconds * 10) / 10,
        wh: Math.round(a.wh * 10000) / 10000,
        cost: Math.round(a.cost * 100000) / 100000,
        tokens: Math.round(a.tokens),
        reason: reason
    });
    flow.set('recent', rec.slice(0, 20));
    task.active = false;
    task.endedAt = now;
    task.gpu = gpu !== null ? gpu : 0;     // gauge drops to idle
    task.gpuTs = now;
    if (S.history.publishOnTaskStop) histTrig = { kind: 'history' };
}

// LLM + GPU details (EventGhost: Ollama /api/ps + nvidia-smi). llm:null = no model loaded.
if (b.llm !== undefined || b.gpu_info !== undefined) {
    const prev = flow.get('llm') || {};
    const num = (v) => { const n = Number(v); return (v === null || v === undefined || v === '' || !isFinite(n)) ? null : n; };
    const str = (v, n) => (v === null || v === undefined) ? '' : String(v).slice(0, n);
    const out = { ts: now, info: prev.info || null, gpu: prev.gpu || null };
    if (b.llm !== undefined) {
        const L = b.llm;
        out.info = (L && typeof L === 'object' && L.model) ? {
            model: str(L.model, 48), family: str(L.family, 16), params: str(L.params, 10), quant: str(L.quant, 12),
            ctx: num(L.ctx), size_gb: num(L.size_gb), vram_gb: num(L.vram_gb),
            gpu_offload_pct: num(L.gpu_offload_pct), loaded: num(L.loaded)
        } : null;
    }
    if (b.gpu_info !== undefined) {
        const G = (b.gpu_info && typeof b.gpu_info === 'object') ? b.gpu_info : {};
        out.gpu = b.gpu_info ? { temp_c: num(G.temp_c), power_w: num(G.power_w), mem_used_mb: num(G.mem_used_mb), mem_total_mb: num(G.mem_total_mb) } : null;
    }
    flow.set('llm', out);
}

if (action === 'start') {
    if (!task.active) begin();
    task.lastEventTs = now;
    if (name !== undefined) task.name = String(name);
} else if (action === 'stop') {
    if (task.active) finish('stop');
} else if (action === 'info') {
    // model/GPU details only - the task state is not touched
} else { // update / heartbeat
    if (task.active) {
        if (gpu === null || gpu >= thr || !S.task.inferFromGpu) task.lastEventTs = now;
        if (name !== undefined) task.name = String(name);
    } else if (S.task.inferFromGpu && gpu !== null && gpu >= thr) {
        begin();
    }
}

flow.set('task', task);
node.status({ fill: task.active ? 'green' : 'grey', shape: 'dot', text: action + (gpu !== null ? ' gpu ' + gpu + '%' : '') + ' -> ' + (task.active ? 'AI active' : 'idle') });
return [reply(200, { ok: true, action: action, active: !!task.active, gpu_pct: gpu }), histTrig];

// Runs every second. While an AI task is active it integrates Netio power into
// session + daily buckets, then publishes the live message to the M5Stack.
// Output 1 -> MQTT out (live), output 2 -> history publish trigger
const S = flow.get('settings');
if (!S) return null;

const now = Date.now();
const r = (v, n) => Math.round(v * Math.pow(10, n)) / Math.pow(10, n);
const dk = (d) => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
const hm = (s) => { const p = String(s).split(':'); return (parseInt(p[0], 10) || 0) * 60 + (parseInt(p[1], 10) || 0); };
function rateAt(d) {
    const T = S.tariff;
    const o = T.offPeak;
    if (o && o.enabled) {
        const m = d.getHours() * 60 + d.getMinutes();
        const a = hm(o.start), z = hm(o.end);
        const inside = a <= z ? (m >= a && m < z) : (m >= a || m < z);
        if (inside) return o.ratePerKwh;
    }
    return T.ratePerKwh;
}

const meta = flow.get('meta') || {};
const task = flow.get('task') || { active: false };
const power = flow.get('power') || null;
const session = flow.get('session') || { start: now, seconds: 0, wh: 0, cost: 0, tokens: 0 };
const daily = flow.get('daily') || {};

let dt = meta.lastTick ? (now - meta.lastTick) / 1000 : 1;
if (!(dt > 0)) dt = 0;
if (dt > 10) dt = 10;               // Node-RED was paused/stalled: don't credit the gap
meta.lastTick = now;

let histTrig = null;
const timeoutMs = (S.task.timeoutSec || 0) * 1000;

// watchdog: the PC stopped talking -> close the task
if (task.active && timeoutMs > 0 && now - (task.lastEventTs || 0) > timeoutMs) {
    const a = task.acc || { seconds: 0, wh: 0, cost: 0, tokens: 0 };
    const rec = flow.get('recent') || [];
    rec.unshift({
        name: task.name || '',
        start: new Date(task.startedAt || now).toISOString(),
        stop: new Date(task.lastEventTs || now).toISOString(),
        seconds: r(a.seconds, 1), wh: r(a.wh, 4), cost: r(a.cost, 5), tokens: Math.round(a.tokens),
        reason: 'timeout'
    });
    flow.set('recent', rec.slice(0, 20));
    task.active = false;
    task.endedAt = now;
    task.gpu = 0;                          // gauge drops to idle
    task.gpuTs = now;
    if (S.history.publishOnTaskStop) histTrig = { kind: 'history' };
}

const day = dk(new Date(now));
const bucket = daily[day] || (daily[day] = { wh: 0, seconds: 0, cost: 0, tokens: 0, tasks: 0 });
const powerFresh = !!power && (now - power.ts) <= (S.netio.staleSec || 30) * 1000;
const gpuFresh = !!task.gpuTs && (now - task.gpuTs) <= Math.max(timeoutMs, 15000);
const gpu = gpuFresh && typeof task.gpu === 'number' ? task.gpu : 0;

if (task.active && dt > 0) {
    let wh = 0, cost = 0;
    if (powerFresh) {
        const base = (S.power.autoBaseline && meta.baselineW !== undefined && meta.baselineW !== null)
            ? meta.baselineW : (S.power.idleBaselineW || 0);
        const eff = Math.max(0, power.w - base);
        wh = eff * dt / 3600;
        cost = (wh / 1000) * rateAt(new Date(now));
    }
    // power above is counted for ANY GPU activity while a task is active; tokens only when the GPU is
    // busy enough to actually be generating (tokens.minGpuPct, default 80)
    const minGpu = S.tokens.minGpuPct === undefined ? 80 : S.tokens.minGpuPct;
    const util = S.tokens.scaleByGpuPct ? Math.max(0, Math.min(100, gpu)) / 100 : 1;
    const tokens = gpu >= minGpu ? (S.tokens.localTokensPerSecond || 0) * dt * util : 0;

    bucket.wh += wh; bucket.seconds += dt; bucket.cost += cost; bucket.tokens += tokens;
    session.wh += wh; session.seconds += dt; session.cost += cost; session.tokens += tokens;
    task.acc = task.acc || { seconds: 0, wh: 0, cost: 0, tokens: 0 };
    task.acc.seconds += dt; task.acc.wh += wh; task.acc.cost += cost; task.acc.tokens += tokens;
} else if (S.power.autoBaseline && powerFresh && dt > 0) {
    const a = Math.min(1, (S.power.autoBaselineAlpha || 0.01) * dt);
    meta.baselineW = (meta.baselineW === undefined || meta.baselineW === null)
        ? power.w : meta.baselineW + a * (power.w - meta.baselineW);
}

// drop days older than the history window (once per day)
if (meta.lastDay !== day) {
    meta.lastDay = day;
    const n = Math.max(1, S.history.days || 30);
    const t = new Date(now);
    const cutoff = dk(new Date(t.getFullYear(), t.getMonth(), t.getDate() - (n - 1)));
    for (const k of Object.keys(daily)) { if (k < cutoff) delete daily[k]; }
}

// scheduled history publish (default hourly)
if (S.history.repeatSec > 0 && now - (meta.lastHistoryPub || 0) >= S.history.repeatSec * 1000) {
    histTrig = { kind: 'history' };
}

const secs = S.session.timeMode === 'wall' ? Math.max(0, (now - session.start) / 1000) : session.seconds;
// cloud-API price of the SESSION's tokens, in USD (the M5 "TOKEN COST" page lists these low -> high)
const share = Math.max(0, Math.min(1, S.tokens.inputShare === undefined ? 0.75 : S.tokens.inputShare));
// usd_per_mtok_blended lets the M5Stack price today's and the 30-day tokens itself
const cloudLive = (S.cloud || []).filter((c) => c.enabled !== false).map((c) => {
    const blended = c.inputUsdPerMTok * share + c.outputUsdPerMTok * (1 - share);
    return { name: c.name, cost: r(session.tokens / 1e6 * blended, 5), usd_per_mtok_blended: r(blended, 4) };
});

// LLM details for the M5Stack live page (null when stale)
const L = flow.get('llm') || null;
const llmFresh = !!L && (now - L.ts) <= (((S.llm && S.llm.staleSec) || 90) * 1000);
let llmLive = null;
if (llmFresh && (L.info || L.gpu)) {
    const I = L.info || {}, G = L.gpu || {};
    llmLive = {
        model: I.model || '', params: I.params || '', quant: I.quant || '',
        ctx: I.ctx ?? null, gpu_offload_pct: I.gpu_offload_pct ?? null,
        vram_used_gb: G.mem_used_mb != null ? r(G.mem_used_mb / 1024, 1) : null,
        vram_total_gb: G.mem_total_mb != null ? r(G.mem_total_mb / 1024, 1) : null,
        temp_c: G.temp_c != null ? Math.round(G.temp_c) : null,
        gpu_power_w: G.power_w != null ? Math.round(G.power_w) : null
    };
}

const live = {
    session: {
        gpu_pct: r(gpu, 1),
        seconds: Math.round(secs),
        energy_wh: r(session.wh, 4),
        cost: r(session.cost, 5),
        tokens: Math.round(session.tokens),
        power_w: powerFresh ? r(power.w, 1) : null,
        active: !!task.active
    },
    today: {
        seconds: Math.round(bucket.seconds),
        energy_wh: r(bucket.wh, 4),
        cost: r(bucket.cost, 5),
        tokens: Math.round(bucket.tokens)
    },
    llm: llmLive,
    cloud: cloudLive,
    currency: S.tariff.currency,
    ts: Math.round(now / 1000)
};

flow.set('meta', meta);
flow.set('task', task);
flow.set('session', session);
flow.set('daily', daily);

node.status({
    fill: task.active ? 'green' : 'grey', shape: 'dot',
    text: (task.active ? 'AI ' : 'idle ') + (powerFresh ? r(power.w, 0) + ' W' : 'no power') + ' | ' + r(session.wh, 2) + ' Wh | ' + r(session.cost, 4)
});

return [{ topic: S.mqtt.telemetryTopic, payload: live, qos: 0, retain: false }, histTrig];

// Session reset. Sources: the M5Stack (hold blue key -> {"action":"reset_session"} on the reset topic)
// or POST /ai/reset. Zeroes the session counters only - the 30-day history is untouched.
// Output 1 -> history publish, output 2 -> HTTP response (only for the REST call)
const S = flow.get('settings');
const now = Date.now();

let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString();
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { /* plain text */ } }
const action = String((p && typeof p === 'object') ? (p.action ?? p.cmd ?? p.command ?? '') : (p ?? '')).toLowerCase();
const accepted = !!msg.res || ['reset_session', 'reset', 'new_session', 'start_session'].includes(action);
if (!accepted) return [null, null];

flow.set('session', { start: now, seconds: 0, wh: 0, cost: 0, tokens: 0 });
node.status({ fill: 'blue', shape: 'dot', text: 'session reset ' + new Date(now).toLocaleTimeString() });

let http = null;
if (msg.res) {
    msg.statusCode = 200;
    msg.payload = { ok: true, session_started: new Date(now).toISOString() };
    http = msg;
}
return [S ? { kind: 'history' } : null, http];

// Builds the 30-day history + cloud-cost comparison.
//  - triggered with {kind:'history'}  -> publishes history (to the M5Stack channel) + full detail (retained)
//  - triggered by GET /ai/stats       -> returns the full detail as the HTTP response
// Output 1 -> MQTT out, output 2 -> HTTP response
const S = flow.get('settings');
if (!S) {
    if (msg.res) { msg.statusCode = 503; msg.payload = { error: 'settings not loaded yet' }; return [null, msg]; }
    return null;
}

const now = Date.now();
const r = (v, n) => Math.round(v * Math.pow(10, n)) / Math.pow(10, n);
const dk = (d) => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');

const daily = flow.get('daily') || {};
const session = flow.get('session') || { start: now, seconds: 0, wh: 0, cost: 0, tokens: 0 };
const task = flow.get('task') || { active: false };
const meta = flow.get('meta') || {};
const power = flow.get('power') || null;

// cloud price comparison for a number of tokens: cost is USD (list prices, what the M5 tiles show),
// cost_gbp is the same converted with fx.usdToGbp
const share = Math.max(0, Math.min(1, S.tokens.inputShare === undefined ? 0.75 : S.tokens.inputShare));
const fx = S.fx.usdToGbp;
const cloud = (tokens) => (S.cloud || []).filter(c => c.enabled !== false).map(c => {
    const blended = c.inputUsdPerMTok * share + c.outputUsdPerMTok * (1 - share);
    const usd = tokens / 1e6 * blended;
    return { name: c.name, cost: r(usd, 5), cost_gbp: r(usd * fx, 5), usd_per_mtok_blended: r(blended, 4) };
});

// last N calendar days, oldest first, zero-filled
const N = Math.max(1, S.history.days || 30);
const t0 = new Date(now);
const days = [];
let tw = 0, ts = 0, tc = 0, tt = 0, tn = 0;
for (let i = N - 1; i >= 0; i--) {
    const k = dk(new Date(t0.getFullYear(), t0.getMonth(), t0.getDate() - i));
    const b = daily[k] || {};
    tw += b.wh || 0; ts += b.seconds || 0; tc += b.cost || 0; tt += b.tokens || 0; tn += b.tasks || 0;
    days.push({
        date: k,
        energy_wh: r(b.wh || 0, 3),
        seconds: Math.round(b.seconds || 0),
        cost: r(b.cost || 0, 5),
        tokens: Math.round(b.tokens || 0),
        tasks: b.tasks || 0
    });
}
const last30 = {
    energy_wh: r(tw, 3), seconds: Math.round(ts), cost: r(tc, 5), tokens: Math.round(tt), tasks: tn,
    daily: days,
    cloud: cloud(tt)
};

// ----- M5Stack history message (same channel as the live feed)
const historyPayload = { last_30d: last30, currency: S.tariff.currency, ts: Math.round(now / 1000) };

// ----- full detail (retained for dashboards / other consumers)
const secs = S.session.timeMode === 'wall' ? Math.max(0, (now - session.start) / 1000) : session.seconds;
const today = days[days.length - 1];
const detail = {
    updated: new Date(now).toISOString(),
    currency: S.tariff.currency,
    ai_active: !!task.active,
    task_name: task.name || '',
    llm: flow.get('llm') || null,
    power_w: power && (now - power.ts) <= (S.netio.staleSec || 30) * 1000 ? r(power.w, 1) : null,
    baseline_w: S.power.autoBaseline && meta.baselineW != null ? r(meta.baselineW, 1) : (S.power.idleBaselineW || 0),
    session: {
        started: new Date(session.start).toISOString(),
        seconds: Math.round(secs),
        compute_seconds: Math.round(session.seconds),
        energy_wh: r(session.wh, 4),
        cost: r(session.cost, 5),
        tokens: Math.round(session.tokens),
        cloud: cloud(session.tokens)
    },
    today: Object.assign({}, today, { cloud: cloud(today.tokens) }),
    last_30d: last30,
    recent_tasks: flow.get('recent') || [],
    assumptions: {
        electricity_rate_per_kwh: S.tariff.ratePerKwh,
        off_peak: S.tariff.offPeak,
        local_tokens_per_second: S.tokens.localTokensPerSecond,
        input_share: share,
        usd_to_gbp: fx,
        cloud_cost_currency: 'USD'
    }
};

if (msg.res) {                       // GET /ai/stats
    msg.statusCode = 200;
    msg.payload = detail;
    return [null, msg];
}

meta.lastHistoryPub = now;
flow.set('meta', meta);
node.status({ fill: 'blue', shape: 'dot', text: 'history sent ' + new Date(now).toLocaleTimeString() + ' | 30d ' + r(tw, 1) + ' Wh' });

return [[
    { topic: S.mqtt.telemetryTopic, payload: historyPayload, qos: 0, retain: false },
    { topic: S.mqtt.detailTopic, payload: detail, qos: 0, retain: true }
], null];

// Fills flow context "daily" with 30 days of fake AI usage, then pushes the history to the M5Stack.
// Your real history is copied to "daily_real_backup" the first time this runs (use RESTORE to put it back).
// Tokens: 0-30 M per day. Power: ~150 W PC base + up to 250 W GPU = 400 W at full GPU load.
const S = flow.get('settings');
if (!S) { node.warn('Settings not loaded - deploy the flow first'); return null; }

if (flow.get('daily_real_backup') === undefined) {
    flow.set('daily_real_backup', JSON.parse(JSON.stringify(flow.get('daily') || {})));
}

const BASE_W = 150, GPU_MAX_W = 250;         // 150 + 250 = 400 W peak
const MAX_TOKENS = 30e6;
const MAX_HOURS = 10;                        // busiest day = ~10 h of AI compute
const rate = S.tariff.ratePerKwh;
const days = Math.max(1, (S.history && S.history.days) || 30);
const dk = (d) => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');

const now = new Date();
const dayDone = (now.getHours() + now.getMinutes() / 60) / 24;   // today is only partly over
const daily = {};
let tw = 0, tc = 0, tt = 0;

for (let i = days - 1; i >= 0; i--) {
    const d = new Date(now.getFullYear(), now.getMonth(), now.getDate() - i);
    const weekend = d.getDay() === 0 || d.getDay() === 6;
    let load = Math.pow(Math.random(), 0.8);                       // 0..1, how busy the day was
    if (weekend) load = Math.min(1, load * 1.25);
    if (Math.random() < 0.12) load = 0;                            // some days with no AI at all
    if (i === 0) load *= dayDone;

    const tokens = Math.round(load * MAX_TOKENS);
    const seconds = Math.round(load * MAX_HOURS * 3600 * (0.85 + 0.3 * Math.random()));
    const gpu = 0.55 + 0.45 * Math.random();                       // average GPU load that day
    const watts = BASE_W + GPU_MAX_W * gpu;
    const wh = watts * seconds / 3600;
    const cost = wh / 1000 * rate;
    const tasks = seconds > 0 ? Math.max(1, Math.round(load * 20 + Math.random() * 4)) : 0;

    daily[dk(d)] = { wh: wh, seconds: seconds, cost: cost, tokens: tokens, tasks: tasks };
    tw += wh; tc += cost; tt += tokens;
}

flow.set('daily', daily);
node.status({ fill: 'yellow', shape: 'dot', text: 'FAKE: ' + (tw / 1000).toFixed(1) + ' kWh, ' + S.tariff.currency + ' ' + tc.toFixed(2) + ', ' + (tt / 1e6).toFixed(0) + 'M tok' });
return { kind: 'history' };

// Puts your real history back (saved by the FAKE node) and pushes it to the M5Stack.
const backup = flow.get('daily_real_backup');
if (backup === undefined) {
    node.status({ fill: 'grey', shape: 'ring', text: 'no backup - real history untouched' });
    return null;
}
flow.set('daily', backup);
flow.set('daily_real_backup', undefined);
node.status({ fill: 'green', shape: 'dot', text: 'real history restored ' + new Date().toLocaleTimeString() });
return { kind: 'history' };
